What is the output of the following C code?

```c
#include <stdio.h>
int main() {
    int x = 5;
    printf("%d %d %d\n", x++, x++, ++x);
    return 0;
}
```

What is the output of the following C++ code?

```cpp
#include <iostream>
using namespace std;
class Base {
public:
    virtual void show() { cout << "Base" << endl; }
};
class Derived : public Base {
public:
    void show() override { cout << "Derived" << endl; }
};
int main() {
    Base *ptr = new Derived();
    ptr->show();
    delete ptr;
    return 0;
}
```

