    return 0;
}
```

What is the output of the following C code?

```c
#include <stdio.h>
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}
int main() {
    int x = 10, y = 20;
    swap(&x, &y);
    printf("%d %d\n", x, y);
    return 0;
}
```

What is the output of the following C code?

```c
#include <stdio.h>
int main() {
    int i;
    for (i = 0; i < 5; i++) {
        if (i == 3)
            continue;
        if (i == 4)
            break;
        printf("%d ", i);
    }
    printf("\n%d\n", i);
    return 0;
}
```

