What is the output of the following C++ code?

```cpp
#include <iostream>
using namespace std;
class MyClass {
    int x;
public:
    MyClass(int val) : x(val) {}
    MyClass operator+(const MyClass& obj) {
        return MyClass(x + obj.x);
    }
    void display() { cout << x << endl; }
};
int main() {
    MyClass a(10), b(20);
    MyClass c = a + b;
    c.display();
    return 0;
}
```
